function mcompare(){
  var rows=[['Afmeting',function(m){return m.dim}],['Oppervlakte',function(m){return m.m2+' m²'}],['Slaapkamers',function(m){return m.beds?m.bed:'Geen (studio)'}],['Sanitair',function(m){return m.id==='villa'?'In overleg':'Douche + apart toilet'}],['Plafondhoogte',function(){return '2,50 m'}],['Vanafprijs',function(m){return m.price==null?'Op aanvraag':eur(m.price)}]];
  return '<section class="mcomp"><div class="wrap"><div class="eyebrow">Vergelijk</div><h2>De modellen naast elkaar</h2><div class="mc-scroll"><table><thead><tr><th></th>'+MODELS.map(function(m){return '<th><a href="#'+mRoute(m.id)+'">'+m.name+'</a></th>'}).join('')+'</tr></thead><tbody>'+
   rows.map(function(r){return '<tr><th>'+r[0]+'</th>'+MODELS.map(function(m){return '<td>'+r[1](m)+'</td>'}).join('')+'</tr>'}).join('')+
   '<tr><th>Altijd inbegrepen</th><td colspan="'+MODELS.length+'">Keuken met apparatuur, airconditioning, ventilatie, elektra, water en riolering, LED-verlichting binnen en buiten, volledig geïsoleerd, turnkey opgeleverd</td></tr></tbody></table></div><p class="imgnote">Alle modellen zijn 4,00 m breed; de lengte groeit mee met het aantal m². Prijzen exclusief btw; opties, transport en plaatsing staan in je offerte.</p></div></section>';}
function renderModelGrid(){
  var list=MODELS.filter(function(m){
    if(F.cat!=='alle'&&m.cat.indexOf(F.cat)<0)return false;
    if(F.opp){var r=F.opp.split('-');if(m.m2<+r[0]||m.m2>+r[1])return false}
    if(F.slp){if(F.slp==='3'?m.beds<3:(m.beds!==+F.slp&&!(F.slp==='2'&&m.id==='villa')))return false}
    if(F.bud){var b=F.bud.split('-');if(m.price==null||m.price<+b[0]||m.price>+b[1])return false}
    if(F.q&&m.name.toLowerCase().indexOf(F.q)<0)return false;
    return true;
  });
  var pv=function(x,d){return x.price==null?d:x.price};var s={pa:function(a,b){return pv(a,1e9)-pv(b,1e9)},pd:function(a,b){return pv(b,-1)-pv(a,-1)},ma:function(a,b){return a.m2-b.m2},md:function(a,b){return b.m2-a.m2}}[F.sort];
  if(s)list=list.slice().sort(s);
  $('#mgrid').innerHTML=list.length?list.map(function(m){return mrow(m)}).join(''):'<div class="empty">Geen modellen gevonden met deze filters.</div>';
  if(typeof reveal==='function')requestAnimationFrame(reveal);
}

