var PHASES=[['Model',[1]],['Indeling',[2]],['Materialen & kleuren',[3,4,5]],['Extra opties',[6,7]],['Overzicht & offerte',[8]]];
function phaseOf(n){for(var i=0;i<PHASES.length;i++)if(PHASES[i][1].indexOf(n)>=0)return i;return 0}
var GEVTAB={label:'Gevel',opts:GEVEL.map(function(g,i){return [g[0],g[1],'gv'+i]})};
function stepper(){
  var ph=phaseOf(S.step);
  return '<div class="stepper"><i class="prog" style="width:'+(ph/4*100)+'%"></i><div class="wrap">'+PHASES.map(function(p,i){var c=i===ph?'cur':(i<ph?'done':'');
    return '<button class="stp '+c+'" data-step="'+p[1][0]+'"><span class="n">'+(c==='done'?I('check',2):(i+1))+'</span>'+p[0]+'</button>'}).join('')+'</div>'+
    (PHASES[ph][1].length>1?'<div class="wrap substeps">'+PHASES[ph][1].map(function(n){return '<button class="'+(n===S.step?'on':(n<S.step?'done':''))+'" data-step="'+n+'">'+(n===3?'Gevel & interieur':STEPS[n-1])+'</button>'}).join('<i></i>')+'</div>':'')+'</div>';
}
