  for(var i=0;i<I18N_ATTR.length;i++){var a=I18N_ATTR[i],cur=n.getAttribute(a);if(cur==null)continue;n.__oa=n.__oa||{};if(n.__oa[a]===undefined||(cur!==n.__oa[a+'_t']&&cur!==n.__oa[a]))n.__oa[a]=cur;var tv=trS(n.__oa[a]);n.__oa[a+'_t']=tv;if(cur!==tv)n.setAttribute(a,tv)}
