  var at=$('#autoT');if(at)at.onchange=function(){S.auto=at.checked;if(!S.auto)cancelAuto();rerender()};
  $$('[data-reset]').forEach(function(b){b.onclick=function(){resetCfg(S.model);rerender()}});
